<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('admin');$teachers=db()->query("SELECT u.id,u.username,u.email,u.full_name,u.is_active,u.last_login_at,GROUP_CONCAT(DISTINCT c.nama_kelas ORDER BY c.nama_kelas SEPARATOR ', ') classes,COUNT(DISTINCT s.id) students,COUNT(DISTINCT CASE WHEN d.tanggal=CURDATE() THEN d.id END) today_reports,COUNT(DISTINCT CASE WHEN d.tanggal>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) THEN d.id END) week_reports FROM users u LEFT JOIN classes c ON c.teacher_id=u.id AND c.aktif=1 LEFT JOIN students s ON s.teacher_id=u.id AND s.status='aktif' LEFT JOIN daily_student_reports d ON d.teacher_id=u.id WHERE u.role='guru' GROUP BY u.id ORDER BY u.full_name")->fetchAll();$pageTitle='Monitoring Guru';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Tenaga Pengajar</p><h1 class="page-title">Monitoring Guru</h1><p class="page-description">Pantau kelas, jumlah siswa, laporan harian, aktivitas, dan status setiap Guru.</p></div><span class="badge badge-blue"><?= count($teachers) ?> Guru</span></div><section class="card"><div class="filter-row"><input class="input" data-search-table="#teachers-table" placeholder="Cari Guru, kelas, atau username..."></div><div class="table-wrap"><table class="table" id="teachers-table"><thead><tr><th>Guru</th><th>Kelas & Siswa</th><th>Laporan Hari Ini</th><th>7 Hari</th><th>Terakhir Login</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($teachers as $teacher):?><tr><td><span class="name"><?= e($teacher['full_name']) ?></span><br><small class="muted"><?= e($teacher['username']) ?><?= $teacher['email']?' · '.e($teacher['email']):'' ?></small></td><td><strong><?= e($teacher['classes']?:'Belum ada kelas') ?></strong><br><small class="muted"><?= (int)$teacher['students'] ?> siswa</small></td><td><strong><?= (int)$teacher['today_reports'] ?>/<?= (int)$teacher['students'] ?></strong></td><td><strong><?= (int)$teacher['week_reports'] ?> laporan</strong></td><td><?= e(format_date_id($teacher['last_login_at'],true)) ?></td><td><span class="badge <?= $teacher['is_active']?'badge-green':'badge-red' ?>"><?= $teacher['is_active']?'Aktif':'Nonaktif' ?></span></td><td><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax><?= csrf_field() ?><input type="hidden" name="action" value="toggle_active"><input type="hidden" name="user_id" value="<?= e($teacher['id']) ?>"><input type="hidden" name="active" value="<?= $teacher['is_active']?'0':'1' ?>"><button class="btn <?= $teacher['is_active']?'btn-danger':'btn-soft' ?> btn-sm" type="submit"><?= $teacher['is_active']?'Nonaktifkan':'Aktifkan' ?></button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>

